import{_ as r,c as a,o,j as n,Y as s,t as i}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"mktemp | x-cmd man (man1) | create a temporary file or directory","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | mktemp - create a temporary file or directory","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"mktemp | x-cmd man (man1) | create a temporary file or directory"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | mktemp - create a temporary file or directory"}]]},"headers":[],"params":{"isMan":true,"man":"mktemp","category":"man1","desc":"create a temporary file or directory"},"relativePath":"man1/mktemp.md","filePath":"man1/[man].md"}'),d={name:"man1/mktemp.md"},m={class:"visually-hidden"};function l(t,e,p,c,g,h){return o(),a("div",null,[n("h1",m,i(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>mktemp - create a temporary file or directory</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>mktemp</strong> [<em>OPTION</em>]... [<em>TEMPLATE</em>]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Create a temporary file or directory, safely, and print its name. TEMPLATE must contain at least 3 consecutive &#39;X&#39;s in last component. If TEMPLATE is not specified, use tmp.XXXXXXXXXX, and <strong>--tmpdir</strong> is implied. Files are created u+rw, and directories u+rwx, minus umask restrictions.</p><dl><dt><strong>-d</strong>, <strong>--directory</strong></dt><dd>create a directory, not a file</dd><dt><strong>-u</strong>, <strong>--dry-run</strong></dt><dd>do not create anything; merely print a name (unsafe)</dd><dt><strong>-q</strong>, <strong>--quiet</strong></dt><dd>suppress diagnostics about file/dir-creation failure</dd><dt><strong>--suffix</strong>=<em>SUFF</em></dt><dd>append SUFF to TEMPLATE; SUFF must not contain a slash. This option is implied if TEMPLATE does not end in X</dd><dt><strong>-p</strong> DIR, <strong>--tmpdir</strong>[=<em>DIR</em>]</dt><dd>interpret TEMPLATE relative to DIR; if DIR is not specified, use $TMPDIR if set, else <em>/tmp</em>. With this option, TEMPLATE must not be an absolute name; unlike with <strong>-t</strong>, TEMPLATE may contain slashes, but mktemp creates only the final component</dd><dt><strong>-t</strong></dt><dd>interpret TEMPLATE as a single file name component, relative to a directory: $TMPDIR, if set; else the directory specified via <strong>-p</strong>; else <em>/tmp</em> [deprecated]</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Jim Meyering and Eric Blake.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>mkstemp</strong>(3), <strong>mkdtemp</strong>(3), <strong>mktemp</strong>(3)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/mktemp%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/mktemp\\</a>&gt; <br> or available locally via: info &#39;(coreutils) mktemp invocation&#39;</p>',16))])}const T=r(d,[["render",l]]);export{f as __pageData,T as default};
